import React from 'react'

function Footer() {
  return (
    <footer className="bg-dark text-white text-cent py-4 mt-5">

      <h4>Contact</h4>

      <p className="mb-1">
        Email: info@example.com
      </p>

      <p className="mb-1">
        Phone: +91 98765 43210
      </p>

      <p className="mb-0">
        © 2026 MyWebsite. All Rights Reserved.
      </p>

    </footer>
  );
}

export default Footer;
